import sys

def read_input():
    data = sys.stdin.read().strip().split()
    if not data:
        return None
    n = int(data[0])
    H = int(data[1])
    points = []
    idx = 2
    for _ in range(n):
        x = int(data[idx])
        y = int(data[idx + 1])
        points.append((x, y))
        idx += 2
    return n, H, points

def distance(p1, p2):
    return ((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2) ** 0.5

def line_segment_intersection(p1, p2, p3, p4):
    # Check if line segment p1-p2 intersects with line segment p3-p4
    # Using cross product method
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    c1 = cross(p1, p2, p3)
    c2 = cross(p1, p2, p4)
    c3 = cross(p3, p4, p1)
    c4 = cross(p3, p4, p2)

    if (c1 * c2 < 0) and (c3 * c4 < 0):
        return True  # Segments intersect

    # Check if endpoints lie on the other segment
    if c1 == 0 and cross(p3, p4, p1) == 0:
        return True
    if c2 == 0 and cross(p3, p4, p2) == 0:
        return True
    if c3 == 0 and cross(p1, p2, p3) == 0:
        return True
    if c4 == 0 and cross(p1, p2, p4) == 0:
        return True

    return False

def solve():
    data = read_input()
    if not data:
        return

    n, H, points = data
    eye = (points[-1][0], points[-1][1] + H)

    total_distance = 0.0

    for i in range(n - 1):
        p1 = points[i]
        p2 = points[i + 1]

        # Check if line from Eye to p1 intersects the segment p1-p2
        if line_segment_intersection(eye, p1, p1, p2):
            total_distance += distance(p1, p2)

    print(total_distance)

if __name__ == "__main__":
    solve()
"}

