import sys

def get_prime_mask(number):
    """Return a bitmask representing prime digits in the number"""
    prime_digits = {2, 3, 5, 7}
    mask = 0

    # Check each digit
    for digit in str(number):
        if int(digit) in prime_digits:
            # Set the corresponding bit
            if digit == '2':
                mask |= 1 << 3  # 2 -> 1000
            elif digit == '3':
                mask |= 1 << 2  # 3 -> 0100
            elif digit == '5':
                mask |= 1 << 1  # 5 -> 0010
            elif digit == '7':
                mask |= 1 << 0  # 7 -> 0001

    return mask

def count_valid_triplets(N, A):
    """Count triplets (i, j, k) with i < j < k and at least one common prime digit"""
    prime_masks = []

    # Get prime digit masks for all numbers
    for number in A:
        prime_masks.append(get_prime_mask(number))

    count = 0

    # Count triplets
    for i in range(N):
        for j in range(i + 1, N):
            for k in range(j + 1, N):
                # Check if they share at least one prime digit
                if (prime_masks[i] & prime_masks[j] & prime_masks[k]) != 0:
                    count += 1

    return count

