        # We need 2A (good), A (nearly good), 3A (nearly good)
        x = 2 * A
        y = A
        z = 3 * A
    else:
        # A * B is good
        # A is nearly good
        # A * (B + 1) is nearly good
        x = A * B
        y = A
        z = A * (B + 1)

    # Check if all conditions are satisfied
    # x + y == z
    if x + y != z:
