import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])

    # Build adjacency list
    adj = [[] for _ in range(N)]
    for i in range(M):
        u = int(data[2 + 2*i]) - 1
        v = int(data[2 + 2*i + 1]) - 1
        adj[u].append(v)
        adj[v].append(u)

    # Check for clique of size 5
    for i in range(N):
        if len(adj[i]) >= 4:
            # Check if neighbors form a clique
            neighbors = adj[i]
            is_clique = True
            for j in range(len(neighbors)):
                for k in range(j + 1, len(neighbors)):
                    if neighbors[k] not in adj[neighbors[j]]:
                        is_clique = False
                        break
                if not is_clique:
                    break
            if is_clique:
                print(i + 1, end=' ')
                for n in neighbors[:4]:
                    print(n + 1, end=' ')
                print()
                return

    # Check for independent set of size 5
    for i in range(N):
        if len(adj[i]) <= N - 5 - 1:
            # Check if non-neighbors form an independent set
            non_neighbors = []
            for j in range(N):
                if j != i and j not in adj[i]:
                    non_neighbors.append(j)
            if len(non_neighbors) >= 5:
                is_independent = True
                for j in range(len(non_neighbors)):
                    for k in range(j + 1, len(non_neighbors)):
                        if non_neighbors[k] in adj[non_neighbors[j]]:
