busy = [0] * n  # busy[i] is the time until which server i+1 is busy

for _ in range(q):
    ti, ki, di = map(int, input().split())

    # Find ki unoccupied servers
    assigned = []
    for i in range(n):
        if busy[i] <= ti:
            assigned.append(i)
            if len(assigned) == ki:
                break

    if len(assigned) == ki:
        # Assign these servers and update their busy times
        total = sum(i + 1 for i in assigned)
        for i in assigned:
            busy[i] = ti + di - 1
        print(total)
    else:
        print(-1)
