from collections import deque

def solve():
    H, W = map(int, input().split())
    grid = [input().strip() for _ in range(H)]

    answer = 0

    # For each black cell, count reachable white cells
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                # BFS from this black cell
                visited = [[False] * W for _ in range(H)]
                queue = deque([(i, j, 0)])  # (row, col, color_index)
                visited[i][j] = True
                white_count = 0

                while queue:
                    r, c, color_idx = queue.popleft()

                    # If we're at a white cell, count it
                    if color_idx % 2 == 1:
                        white_count += 1
                    else:
                        # If we're at a black cell, we can only move to white cells
                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < H and 0 <= nc < W and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc, color_idx + 1))
                    else:
                        # If we're at a white cell, we can only move to black cells
                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < H and 0 <= nc < W and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc, color_idx + 1))

                answer += white_count

    print(answer)

solve()
