import sys

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        message = sys.stdin.readline().strip()

        # Create substitution cipher
        cipher = {}
        current_char = 'a'

        # Map each unique letter to the next available character
        for char in message:
            if char not in cipher:
                cipher[char] = current_char
                current_char = chr(ord(current_char) + 1)

        # Encode the message using the cipher
        encoded = ''.join([cipher[char] for char in message])

        print(encoded)

if __name__ == "__main__":
