import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    l = int(next(it))

    a = [int(next(it)) for _ in range(n)]

    for _ in range(m):
        t = int(next(it))
        if t == 0:
            # Count blocks of consecutive values > l
            blocks = 0
            prev = -1
            for i in range(n):
                if a[i] > l:
                    if prev <= l:
                        blocks += 1
                    prev = a[i]
                else:
                    prev = a[i]
            print(blocks)
        else:
            p = int(next(it)) - 1  # 0-indexed
            d = int(next(it))
            a[p] += d

if __name__ == "__main__":
    solve()
