def smallest_number_with_digit_sum(s):
    """Return the smallest number with digit sum s"""
    if s % 9 == 0:
        return 10**(s // 9) - 1
    else:
        return 10**(s // 9) + (s % 9)

n = int(input())
bi = [int(input()) for _ in range(n)]

# Find the smallest numbers for each b_i
ai = [smallest_number_with_digit_sum(b) for b in bi]

# Check if the sequence is strictly increasing
# If not, increment the last number until it is
while ai[-1] <= ai[-2]:
    ai[-1] += 1

# Print the result
for num in ai:
    print(num)
